const response = $json.choices[0].message.content;

const riskAssessment = JSON.parse(response);

return [
  {
    json: {
      analysis_request_id: $('Fetch AI Analysis').first().json.analysis_request_id,

      market_risks: riskAssessment.market_risks,
      technical_risks: riskAssessment.technical_risks,
      business_risks: riskAssessment.business_risks,
      financial_risks: riskAssessment.financial_risks,
      legal_and_regulatory_risks: riskAssessment.legal_and_regulatory_risks,
      operational_challenges: riskAssessment.operational_challenges,
      risk_mitigation_strategies: riskAssessment.risk_mitigation_strategies,
      overall_risk_level: riskAssessment.overall_risk_level,
      risk_summary: riskAssessment.risk_summary,
      analysis_status: riskAssessment.analysis_status,
      confidence_score: riskAssessment.confidence_score
    }
  }
];
